"""Markdown evaluation report generated by ``make eval`` (do not edit the output)."""

from __future__ import annotations

import os
from pathlib import Path
from typing import Any

from recsys.config import Config


def _pct(x: float | None) -> str:
    return "n/a" if x is None else f"{x * 100:+.1f}%"


def write_markdown(result: dict[str, Any], cfg: Config, figures: list[Path], out: Path) -> Path:
    ec = cfg.evaluation
    m = ec.primary_metric
    lines = [
        f"# Evaluation report ({result['split']} split)",
        "",
        "<!-- Generated by `make eval` (recsys.eval.offline). Do not edit. -->",
        "",
        f"- Cutoff {result['cutoff_date']}; {result['visitors_with_truth']:,} visitors with ≥ 1 future interaction "
        f"({result['warm_visitors']:,} returning).",
        f"- Bootstrap: {result['bootstrap_samples']:,} resamples of visitors, {result['confidence']:.0%} percentile intervals.",
        f"- Simulated A/B: visitors hashed 50/50 with salt `{result['ab_salt']}` "
        f"(treatment share {result['ab_treatment_share']:.3f}); each arm scored only with its own policy.",
        "",
    ]
    for f in figures:
        rel = os.path.relpath(f, out.parent)
        lines += [f"![{f.stem}]({rel})", ""]
    lines += ["## Policy summary", ""]
    for seg in ("all", "warm", "cold"):
        rows = sorted((r for r in result["summary"] if r["segment"] == seg), key=lambda r: -r[m])
        if not rows:
            continue
        lines += [
            f"### {seg} ({rows[0]['users']:,} visitors)",
            "",
            "| policy | NDCG@10 (95% CI) | Recall@10 | Recall@20 | Recall@100 | MAP@10 | HR@10 |",
            "|---|---|---:|---:|---:|---:|---:|",
        ]
        for r in rows:
            lo, hi = r[f"{m}_ci"]
            lines.append(
                f"| `{r['policy']}` | {r[m]:.4f} [{lo:.4f}, {hi:.4f}] | {r['recall_at_10']:.4f} | "
                f"{r['recall_at_20']:.4f} | {r['recall_at_100']:.4f} | {r['map_at_10']:.4f} | {r['hit_rate_at_10']:.4f} |"
            )
        lines.append("")
    lines += [
        "## Comparisons",
        "",
        "Relative lift = treatment / control − 1 (n/a when the control scores 0). `p_not_better` = share of bootstrap replicates with treatment − control ≤ 0. "
        "Significant = the 95% CI of the absolute difference excludes 0.",
        "",
        "| metric | treatment vs control | segment | design | control | treatment | lift (95% CI) | p_not_better | significant |",
        "|---|---|---|---|---:|---:|---|---:|---|",
    ]
    for r in result["comparisons"]:
        lift = r["rel_lift"]
        lines.append(
            f"| {r['metric']} | {r['treatment']} vs {r['control']} | {r['segment']} | {r['design']} | "
            f"{r['control_mean']:.4f} | {r['treatment_mean']:.4f} | {_pct(lift['estimate'])} "
            f"[{_pct(lift['low'])}, {_pct(lift['high'])}] | {r['p_not_better']:.3f} | {'yes' if r['significant'] else 'no'} |"
        )
    lines += [
        "",
        "## Beyond accuracy (top-10 lists)",
        "",
        "Coverage = distinct recommended items / items in the catalog at T. Diversity = mean share of item pairs in a list "
        "with different categories. Novelty = mean −log2 of the item's 30-day visitor share (higher = less popular). "
        "Median popularity rank: 1 = most popular.",
        "",
        "| policy | catalog coverage | distinct items | diversity | novelty (bits) | median popularity rank |",
        "|---|---:|---:|---:|---:|---:|",
    ]
    for r in sorted(result["beyond_accuracy"], key=lambda r: r["source"]):
        div = r.get("diversity_at_10")
        lines.append(
            f"| `{r['source']}` | {r['catalog_coverage_at_10']:.2%} | {r['distinct_items_at_10']:,} | "
            f"{'—' if div is None else f'{div:.3f}'} | {r['novelty_at_10']:.2f} | {r['median_popularity_rank_at_10'] or '—'} |"
        )
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text("\n".join(lines) + "\n")
    return out
